68	/* Single chat message */
69	typedef struct {
70	    char text[LVGL_UI_MSG_MAX_LEN]; /* Message text, truncated to 512 bytes */
71	    bool is_user; /* true = user message, false = Agent reply */
72	    lv_obj_t* bubble; /* Corresponding LVGL bubble widget */
73	} chat_msg_t;
74	
75	/* Chat history ring buffer */
76	typedef struct {
77	    chat_msg_t msgs[CHAT_HISTORY_MAX]; /* Ring buffer slots */
78	    int head; /* Next write position */
79	    int count; /* Current message count */
80	} chat_history_t;
