183	int lvgl_ui_channel_init(void)
184	{
185	    int chat_h;
186	    int ret = 0;
187	
188	    /* Idempotent: already initialized */
189	    if (s_state.initialized) {
190	        return 0;
191	    }
192	
193	    syslog(LOG_INFO, "[%s] init\n", TAG);
194	
195	    /* Do NOT call lv_init() — the system (miwear) already initialized
196	     * LVGL and owns the display + event loop.  We only create our UI
197	     * widgets on the existing LVGL instance. */
198	
199	    /* Do NOT create a display or allocate a display buffer — the system
200	     * already has one.  Creating a second display causes resource
201	     * conflicts and framebuffer contention. */
202	
203	    /* Create main screen with dark background */
204	    s_state.screen = lv_obj_create(NULL);
205	    if (!s_state.screen) {
206	        syslog(LOG_ERR, "[%s] screen create failed\n", TAG);
207	        ret = -EIO;
208	        goto cleanup;
209	    }
210	
211	    lv_obj_set_style_bg_color(s_state.screen, lv_color_hex(0x1a1a2e), 0);
212	    lv_obj_set_style_bg_opa(s_state.screen, LV_OPA_COVER, 0);
213	    /* Do NOT call lv_screen_load() here — we load the screen on
214	     * demand when the user activates the chat UI, to avoid
215	     * hijacking the system's current screen at boot. */
216	
217	    /* Defer CJK font creation to the LVGL thread (show_screen_async_cb).
218	     * Creating a FreeType font here — from the main thread — causes
219	     * FT_Err_Invalid_Size_Handle (0x55) because the FreeType size
220	     * object races with the LVGL render thread.  Use Montserrat as
221	     * a safe placeholder until the screen is shown. */
222	    s_state.font = NULL;
223	    lv_obj_set_style_text_font(s_state.screen, &lv_font_montserrat_14, 0);
224	
225	    /* Step 5: Create Chat View container */
226	    chat_h = LVGL_UI_SCREEN_H - LVGL_UI_PADDING_TOP - LVGL_UI_PADDING_BOTTOM
227	        - LVGL_UI_PTT_SIZE - 20;
228	
229	    s_state.chat_list = lv_obj_create(s_state.screen);
230	    if (!s_state.chat_list) {
231	        syslog(LOG_ERR, "[%s] chat_list create failed\n", TAG);
232	        ret = -EIO;
233	        goto cleanup;
234	    }
235	
236	    lv_obj_set_size(s_state.chat_list,
237	        LVGL_UI_SCREEN_W - 2 * LVGL_UI_PADDING_H, chat_h);
238	    lv_obj_align(s_state.chat_list, LV_ALIGN_TOP_MID, 0, LVGL_UI_PADDING_TOP);
239	    lv_obj_set_scroll_dir(s_state.chat_list, LV_DIR_VER);
240	    lv_obj_set_flex_flow(s_state.chat_list, LV_FLEX_FLOW_COLUMN);
241	    lv_obj_set_style_pad_row(s_state.chat_list, LVGL_UI_CHAT_GAP, 0);
242	    lv_obj_set_style_bg_opa(s_state.chat_list, LV_OPA_TRANSP, 0);
243	    lv_obj_set_style_border_width(s_state.chat_list, 0, 0);
244	    lv_obj_set_style_pad_left(s_state.chat_list, 4, 0);
245	    lv_obj_set_style_pad_right(s_state.chat_list, 4, 0);
246	    lv_obj_set_style_pad_top(s_state.chat_list, 4, 0);
247	    lv_obj_set_style_pad_bottom(s_state.chat_list, 4, 0);
248	    lv_obj_set_scrollbar_mode(s_state.chat_list, LV_SCROLLBAR_MODE_OFF);
249	    lv_obj_add_flag(s_state.chat_list, LV_OBJ_FLAG_SCROLL_MOMENTUM);
250	
251	    /* Step 6: Create PTT Button */
252	    s_state.ptt_btn = lv_btn_create(s_state.screen);
253	    if (!s_state.ptt_btn) {
254	        syslog(LOG_ERR, "[%s] ptt_btn create failed\n", TAG);
255	        ret = -EIO;
256	        goto cleanup;
257	    }
258	
259	    lv_obj_set_size(s_state.ptt_btn, LVGL_UI_PTT_SIZE, LVGL_UI_PTT_SIZE);
260	    lv_obj_align(s_state.ptt_btn, LV_ALIGN_BOTTOM_MID, 0, -LVGL_UI_PADDING_BOTTOM);
261	    lv_obj_set_style_radius(s_state.ptt_btn, LVGL_UI_PTT_SIZE / 2, 0);
262	    lv_obj_set_style_bg_color(s_state.ptt_btn, lv_color_hex(0x4a90d9), 0);
263	    lv_obj_set_style_shadow_width(s_state.ptt_btn, 12, 0);
264	    lv_obj_set_style_shadow_color(s_state.ptt_btn, lv_color_hex(0x4a90d9), 0);
265	    lv_obj_set_style_shadow_opa(s_state.ptt_btn, LV_OPA_40, 0);
266	
267	    s_state.ptt_label = lv_label_create(s_state.ptt_btn);
268	    if (!s_state.ptt_label) {
269	        syslog(LOG_ERR, "[%s] ptt_label create failed\n", TAG);
270	        ret = -EIO;
271	        goto cleanup;
272	    }
273	
274	    /* Use Unicode microphone emoji — MiSans includes it, unlike
275	     * LV_SYMBOL_AUDIO which needs FontAwesome glyphs not in MiSans
276	     * and renders as a rectangle. */
277	    lv_label_set_text(s_state.ptt_label, PTT_ICON_MIC);
278	    lv_obj_center(s_state.ptt_label);
279	
280	    lv_obj_add_event_cb(s_state.ptt_btn, ptt_btn_event_cb, LV_EVENT_ALL, NULL);
281	
282	    /* Step 7: Create Recording Indicator (initially hidden) */
283	    s_state.rec_indicator = lv_label_create(s_state.screen);
284	    if (!s_state.rec_indicator) {
285	        syslog(LOG_ERR, "[%s] rec_indicator create failed\n", TAG);
286	        ret = -EIO;
287	        goto cleanup;
288	    }
289	
290	    lv_label_set_text(s_state.rec_indicator, "");
291	    lv_obj_align_to(s_state.rec_indicator, s_state.ptt_btn, LV_ALIGN_OUT_TOP_MID, 0, -8);
292	    lv_obj_add_flag(s_state.rec_indicator, LV_OBJ_FLAG_HIDDEN);
293	
294	    /* Step 7b: Create Close Button (top-right corner) */
295	    s_state.close_btn = lv_btn_create(s_state.screen);
296	    if (!s_state.close_btn) {
297	        syslog(LOG_ERR, "[%s] close_btn create failed\n", TAG);
298	        ret = -EIO;
299	        goto cleanup;
300	    }
301	
302	    lv_obj_set_size(s_state.close_btn, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
303	    /* Position close button inside the visible circular area.
304	     * On a 466x466 round screen (radius 233), the top-right corner
305	     * is clipped by the bezel.  Place the button at a position that
306	     * is safely inside the circle: top-center with a rightward offset.
307	     * At y=30 from top, the visible horizontal range is roughly
308	     * center ± sqrt(233²-203²) ≈ ±115px, so x offset of +80 is safe. */
309	    lv_obj_align(s_state.close_btn, LV_ALIGN_TOP_MID, 80, LVGL_UI_PADDING_TOP - 30);
310	    lv_obj_set_style_bg_opa(s_state.close_btn, LV_OPA_TRANSP, 0);
311	    lv_obj_set_style_border_width(s_state.close_btn, 0, 0);
312	    lv_obj_set_style_shadow_opa(s_state.close_btn, LV_OPA_TRANSP, 0);
313	    lv_obj_set_style_pad_all(s_state.close_btn, 8, 0);
314	
315	    lv_obj_t* close_label = lv_label_create(s_state.close_btn);
316	    if (close_label) {
317	        lv_label_set_text(close_label, CLOSE_BTN_TEXT);
318	        lv_obj_set_style_text_color(close_label, lv_color_hex(0x999999), 0);
319	        lv_obj_center(close_label);
320	    }
321	
322	    lv_obj_add_event_cb(s_state.close_btn, close_btn_event_cb, LV_EVENT_CLICKED, NULL);
323	
324	    /* Step 8: Initialize chat history and mutex */
325	    memset(&s_state.history, 0, sizeof(chat_history_t));
326	    pthread_mutex_init(&s_state.lock, NULL);
327	
328	    s_state.initialized = true;
329	    syslog(LOG_INFO, "[%s] init OK\n", TAG);
330	    return 0;
331	
332	cleanup:
333	    /* Release resources in reverse order (coding-2) */
334	    if (s_state.font) {
335	        vg_font_destroy(s_state.font);
336	        s_state.font = NULL;
337	    }
338	
339	    if (s_state.screen) {
340	        lv_obj_del(s_state.screen);
341	        s_state.screen = NULL;
342	        /* Child widgets are deleted with the screen */
